package fraymus.workspace;
import org.json.*;
import java.util.*;
/** Conservative finite order/clearance planning; the virtual gripper's actuation is explicit. */
final class WorldPlan {
 static final String PROCEDURE="persistent-world-arrange-v1",VERSION="lifted-pose-plan-035-v1";
 static final String SCOPE="Versioned persistent native box world, paused between goals; bounded virtual force/torque gripper and exact kinematic cold handoff, not contact-only pushing, a physical robot hand, photographic recognition or LLM-weight training.";
 static JSONArray quat(double yaw){double a=Math.toRadians(yaw)/2;return new JSONArray(new double[]{0,Math.sin(a),0,Math.cos(a)});}
 static double yaw(JSONArray q){return Math.toDegrees(Math.atan2(2*(q.getDouble(3)*q.getDouble(1)+q.getDouble(0)*q.getDouble(2)),1-2*(q.getDouble(1)*q.getDouble(1)+q.getDouble(2)*q.getDouble(2))));}
 static double[] rotationError(JSONArray target,JSONArray current){double x=target.getDouble(0),y=target.getDouble(1),z=target.getDouble(2),w=target.getDouble(3),a=-current.getDouble(0),b=-current.getDouble(1),c=-current.getDouble(2),d=current.getDouble(3);double[] e={w*a+x*d+y*c-z*b,w*b-x*c+y*d+z*a,w*c+x*b-y*a+z*d};double ew=w*d-x*a-y*b-z*c;if(ew<0){ew=-ew;for(int i=0;i<3;i++)e[i]=-e[i];}double n=ObserverGeometry.norm(e),angle=2*Math.atan2(n,Math.max(0,ew));for(int i=0;i<3;i++)e[i]=n<1e-12?0:e[i]/n*angle;return e;}
 static double angle(JSONArray a,JSONArray b){return Math.toDegrees(ObserverGeometry.norm(rotationError(a,b)));}
 static double radius(JSONObject o){return ObserverGeometry.norm(SpatialScene.vector(o.getJSONArray("size"),40))/2+.025;}
 static JSONObject intent(JSONObject scene,JSONArray targets,double force,double torque){RampDefinition.range(force,2,60,"virtual gripper force N");RampDefinition.range(torque,0,4,"virtual gripper torque Nm");if(targets.length()<2||targets.length()>4)throw new IllegalArgumentException("Arrange2..4 distinct dynamic bodies");var ids=new HashSet<String>();for(Object raw:targets){var t=(JSONObject)raw;SpatialScene.keys(t,"sourceId","positionM","yawDeg");String id=t.getString("sourceId");if(!ids.add(id))throw new IllegalArgumentException("Repeated pose role");var o=sourceObject(scene,id);if(o.getDouble("massKg")<=0)throw new IllegalArgumentException("Target a dynamic source role");double[] p=SpatialScene.vector(t.getJSONArray("positionM"),5);if(Math.abs(p[1]-o.getJSONArray("size").getDouble(1)/2)>.001)throw new IllegalArgumentException("Pose targets must finish upright on the floor");SpatialScene.number(t,"yawDeg",-180,180);}
  return new JSONObject().put("binding",SpatialStore.binding(scene)).put("targets",new JSONArray(targets.toString())).put("forceLimitN",force).put("torqueLimitNm",torque).put("actuator","bounded virtual force/torque gripper");}
 static JSONObject sourceObject(JSONObject scene,String source){for(Object raw:scene.getJSONArray("objects")){var o=(JSONObject)raw;if(o.getString("sourceId").equals(source))return o;}throw new IllegalArgumentException("Unknown actual source role: "+source);}
 static JSONObject build(JSONObject scene,JSONObject intent){
  if(intent.has("construction051"))return Construction051.plan(scene,intent);
  WorldFrames.verifyScene(scene);if(!intent(scene,intent.getJSONArray("targets"),intent.getDouble("forceLimitN"),intent.getDouble("torqueLimitNm")).similar(intent))throw new IllegalStateException("Pose source/intent changed");JSONObject floor=null;double top=0,radius=0;var positions=new LinkedHashMap<String,double[]>();
  for(Object raw:scene.getJSONArray("objects")){var o=(JSONObject)raw;double[] p=SpatialScene.vector(o.getJSONArray("position"),20),s=SpatialScene.vector(o.getJSONArray("size"),40);var q=o.getJSONArray("rotation");if(Math.abs(q.getDouble(0))+Math.abs(q.getDouble(2))>.043)throw new IllegalArgumentException("Pose task sources must be upright; yaw rotations are supported");if(o.getString("sourceId").equals("floor")){floor=o;continue;}if(o.getDouble("massKg")>0){if(o.getDouble("massKg")<.2||o.getDouble("massKg")>4||s[0]>1||s[1]>1||s[2]>1||Math.abs(p[1]-s[1]/2)>.05)throw new IllegalArgumentException("Use upright0.2..4kg boxes of at most1m, resting on the floor");positions.put(o.getString("sourceId"),p);}top=Math.max(top,p[1]+s[1]/2);radius=Math.max(radius,radius(o));}
  if(floor==null||floor.getDouble("massKg")!=0||Math.abs(floor.getJSONArray("position").getDouble(1)+floor.getJSONArray("size").getDouble(1)/2)>.001)throw new IllegalArgumentException("Require an explicit flat static floor atY=0");
  double lift=top+radius+.25;if(lift>4)throw new IllegalArgumentException("Lift clearance exceeds4m supported height");var remaining=new ArrayList<JSONObject>();for(Object raw:intent.getJSONArray("targets"))remaining.add((JSONObject)raw);var ordered=new JSONArray();boolean passed=order(scene,floor,remaining,positions,lift,ordered);
  return new JSONObject().put("version",VERSION).put("scope",SCOPE).put("intent",intent).put("liftHeightM",lift).put("orderedTargets",ordered).put("passed",passed).put("reason",passed?"Conservative lifted routes and target order are clear":"No supported clear lifted route/order; target occupancy, cyclic swaps or overhangs require a different plan");
 }
 private static boolean order(JSONObject scene,JSONObject floor,List<JSONObject> todo,Map<String,double[]> positions,double lift,JSONArray out){if(todo.isEmpty())return true;for(int i=0;i<todo.size();i++){var t=todo.get(i);var o=sourceObject(scene,t.getString("sourceId"));double[] from=positions.get(o.getString("sourceId")),to=SpatialScene.vector(t.getJSONArray("positionM"),5);double r=radius(o);double[] fp=SpatialScene.vector(floor.getJSONArray("position"),20),fs=SpatialScene.vector(floor.getJSONArray("size"),40);if(Math.abs(to[0]-fp[0])+r>fs[0]/2-.05||Math.abs(to[2]-fp[2])+r>fs[2]/2-.05)continue;
    double[][] path={from,{from[0],lift,from[2]},{to[0],lift,to[2]},to};boolean clear=true;for(int leg=0;leg<3&&clear;leg++)clear=clear(scene,o.getString("sourceId"),positions,path[leg],path[leg+1],r);if(!clear)continue;
    var next=new ArrayList<>(todo);next.remove(i);var placed=new LinkedHashMap<>(positions);placed.put(o.getString("sourceId"),to);var tail=new JSONArray();if(order(scene,floor,next,placed,lift,tail)){out.put(new JSONObject(t.toString()).put("objectId",o.getString("id")).put("rotation",quat(t.getDouble("yawDeg"))));for(Object v:tail)out.put(v);return true;}}
   return false;}
 static boolean clear(JSONObject scene,String selected,Map<String,double[]> positions,double[] a,double[] b,double radius){for(Object raw:scene.getJSONArray("objects")){var o=(JSONObject)raw;String id=o.getString("sourceId");if(id.equals(selected)||id.equals("floor"))continue;double[] p=positions.getOrDefault(id,SpatialScene.vector(o.getJSONArray("position"),20)),size=SpatialScene.vector(o.getJSONArray("size"),40);double yaw=Math.toRadians(yaw(o.getJSONArray("rotation"))),co=Math.cos(yaw),si=Math.sin(yaw);double[] aa={co*(a[0]-p[0])-si*(a[2]-p[2]),a[1]-p[1],si*(a[0]-p[0])+co*(a[2]-p[2])},bb={co*(b[0]-p[0])-si*(b[2]-p[2]),b[1]-p[1],si*(b[0]-p[0])+co*(b[2]-p[2])};double lo=0,hi=1;for(int n=0;n<64;n++){double x=(2*lo+hi)/3,y=(lo+2*hi)/3;if(clearance(aa,bb,x,size,o.getDouble("massKg")>0)<clearance(aa,bb,y,size,o.getDouble("massKg")>0))hi=y;else lo=x;}if(clearance(aa,bb,(lo+hi)/2,size,o.getDouble("massKg")>0)<radius*radius)return false;}return true;}
 private static double clearance(double[] a,double[] b,double t,double[] size,boolean dynamic){double sum=0;if(dynamic){double radius=ObserverGeometry.norm(size)/2+.025,n=0;for(int k=0;k<3;k++){double x=a[k]+(b[k]-a[k])*t;n+=x*x;}double d=Math.max(0,Math.sqrt(n)-radius);return d*d;}for(int k=0;k<3;k++){double d=Math.max(0,Math.abs(a[k]+(b[k]-a[k])*t)-size[k]/2);sum+=d*d;}return sum;}
 static void verify(JSONObject scene,JSONObject plan){if(!build(scene,plan.getJSONObject("intent")).similar(plan)||!plan.getBoolean("passed"))throw new IllegalStateException("Original pose plan is changed or rejected");}

}
